/* Front-end prototype helper: makes forms and buttons click through without a backend. */
(function () {
  'use strict';
  var KEY = 'maa-proto-selections';
  var go = function (url) { window.location.href = url; };
  var toast = function (msg) {
    var t = document.createElement('div');
    t.className = 'proto-toast'; t.setAttribute('role', 'status'); t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 3500);
  };

  function routeFor(form, submitter) {
    var action = (submitter && submitter.getAttribute('formaction')) || form.getAttribute('action') || location.pathname;
    var method = (form.getAttribute('method') || 'get').toLowerCase();
    if (method === 'get') return null; // filters/search: just reload same page
    if (action === '/vote') {
      var code = (form.querySelector('[name=code]') || {}).value || '';
      var c = code.toUpperCase().replace(/[^A-Z0-9]/g, '');
      if (c.length < 16 || c.indexOf('AAAA') === 0) return '/vote-invalid';
      if (c.indexOf('USED') === 0) return '/already-voted';
      return '/ballot';
    }
    if (action === '/ballot') return '/ballot/review';
    if (action === '/ballot/submit') return '/thank-you';
    if (action === '/exit') return '/';
    if (action === '/admin/login') return '/admin';
    if (action === '/admin/logout') return '/admin/login';
    if (action === '/admin/invitations/confirm') return '/admin/invitations/confirm';
    if (action === '/admin/voters/approve-list') return '/admin/codes';
    if (action === '/admin/codes/generate') return '/admin/invitations';
    if (action === '/admin/import') return '/admin/import';
    if (/^\/admin\/(candidates|voters)\/?$/.test(action)) return action.replace(/\/$/, '');
    return 'stay';
  }

  // Remember ballot choices so the review page reflects what was clicked.
  function rememberBallot(form) {
    var out = [];
    form.querySelectorAll('fieldset.position').forEach(function (fs) {
      var h = fs.querySelector('h2');
      var checked = fs.querySelector('input[type=radio]:checked');
      var name = checked ? (checked.value === 'abstain' ? 'Abstain' : checked.closest('label').querySelector('.name').textContent) : null;
      out.push({ pos: h ? h.textContent.trim() : '', sel: name });
    });
    try { sessionStorage.setItem(KEY, JSON.stringify(out)); } catch (e) { /* ignore */ }
  }

  document.addEventListener('submit', function (e) {
    var form = e.target;
    if (e.defaultPrevented) return; // e.g. incomplete-ballot validation
    var route = routeFor(form, e.submitter);
    if (route === null) { e.preventDefault(); toast('Prototype: filtering and search are not active.'); return; }
    e.preventDefault();
    if (form.id === 'ballot-form') rememberBallot(form);
    if (route === 'stay') {
      form.dataset.submitting = '';
      form.querySelectorAll('button[type=submit]').forEach(function (b) { b.disabled = false; if (b.dataset.label) b.textContent = b.dataset.label; });
      toast('Prototype: this action would be saved in the real app.');
      return;
    }
    go(route);
  });

  // Review page: show the choices made on the ballot page.
  if (location.pathname.replace(/\.html$/, '') === '/ballot/review') {
    try {
      var saved = JSON.parse(sessionStorage.getItem(KEY) || '[]');
      document.querySelectorAll('.review-list li').forEach(function (li) {
        var pos = li.querySelector('.pos');
        var sel = li.querySelector('.sel');
        if (!pos || !sel) return;
        var hit = saved.filter(function (s) { return s.pos === pos.textContent.trim(); })[0];
        if (hit && hit.sel) { sel.textContent = hit.sel; sel.classList.toggle('abstain', hit.sel === 'Abstain'); }
      });
    } catch (e) { /* ignore */ }
  }

  // Code reveal buttons on admin pages
  document.querySelectorAll('[data-reveal-code]').forEach(function (btn) {
    var clone = btn.cloneNode(true);
    btn.parentNode.replaceChild(clone, btn);
    clone.addEventListener('click', function () {
      var t = document.getElementById(clone.getAttribute('data-target'));
      if (t) t.textContent = 'DEMO-CODE-XXXX-XXXX';
      toast('Prototype: real codes are only shown in the real app.');
    });
  });

  // Export / download links have no backend in the prototype.
  document.querySelectorAll('a[href*="export"], a[href$=".csv"], a[href$=".xlsx"]').forEach(function (a) {
    a.addEventListener('click', function (e) { e.preventDefault(); toast('Prototype: exports are generated by the real app.'); });
  });
})();
